content:
Below is a reusable Terraform module for the requested S3 bucket, PostgreSQL RDS instance, and IAM role for Kubernetes service accounts. It supports dev/prod through separate workspaces and tfvars, including production cross-region S3 replication.

The RDS master password is generated and managed by AWS Secrets Manager, so it is not committed to Git or passed through plaintext tfvars.

> The broader canonical scenario mentions EKS and HTTPS resources, but those are not provisioned here because this module is scoped to the three resources requested. The IAM role accepts an existing EKS OIDC provider.

## Repository structure

```text
.
├── main.tf
├── outputs.tf
├── providers.tf
├── variables.tf
├── versions.tf
├── environments
│   ├── dev.tfvars
│   └── prod.tfvars
└── modules
    └── app-data
        ├── iam.tf
        ├── outputs.tf
        ├── rds.tf
        ├── s3.tf
        ├── variables.tf
        └── versions.tf
```

## Root module

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Configure this during initialization or replace it with your own backend.
  #
  # Use a separate workspace for each environment:
  #   terraform workspace new dev
  #   terraform workspace new prod
  backend "s3" {}
}
```

### `providers.tf`

```hcl
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = merge(var.tags, {
      Environment = var.environment
      ManagedBy   = "Terraform"
    })
  }
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region

  default_tags {
    tags = merge(var.tags, {
      Environment = var.environment
      ManagedBy   = "Terraform"
    })
  }
}
```

### `variables.tf`

```hcl
variable "environment" {
  description = "Deployment environment."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "aws_region" {
  description = "Primary AWS region."
  type        = string
}

variable "replica_region" {
  description = "Region for the production S3 replica bucket."
  type        = string
  default     = "us-west-2"
}

variable "name_prefix" {
  description = "Prefix used for resource names."
  type        = string
}

variable "bucket_name" {
  description = "Globally unique primary S3 bucket name."
  type        = string
}

variable "replica_bucket_name" {
  description = "Globally unique replica bucket name. Required when replication is enabled."
  type        = string
  default     = null
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
}

variable "db_allocated_storage" {
  description = "Initial RDS storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Maximum autoscaled RDS storage in GiB."
  type        = number
  default     = 100
}

variable "db_name" {
  description = "Initial PostgreSQL database name."
  type        = string
  default     = "app"
}

variable "db_username" {
  description = "PostgreSQL master username."
  type        = string
  default     = "appadmin"
}

variable "db_subnet_ids" {
  description = "Private subnet IDs used by RDS."
  type        = list(string)
}

variable "db_security_group_ids" {
  description = "Security group IDs attached to RDS."
  type        = list(string)
}

variable "oidc_provider_arn" {
  description = "ARN of the EKS IAM OIDC provider."
  type        = string
}

variable "oidc_issuer_url" {
  description = "EKS OIDC issuer URL, with or without https://."
  type        = string
}

variable "service_account_namespace" {
  description = "Kubernetes namespace containing the service account."
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account name."
  type        = string
  default     = "web-app"
}

variable "tags" {
  description = "Additional resource tags."
  type        = map(string)
  default     = {}
}
```

### `main.tf`

```hcl
check "workspace_matches_environment" {
  assert {
    condition     = terraform.workspace == var.environment
    error_message = "Select the ${var.environment} workspace before applying."
  }
}

module "app_data" {
  source = "./modules/app-data"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  name_prefix        = var.name_prefix
  environment        = var.environment
  bucket_name        = var.bucket_name
  replica_bucket_name = var.replica_bucket_name

  enable_replication = var.environment == "prod"

  db_instance_class         = var.db_instance_class
  db_allocated_storage      = var.db_allocated_storage
  db_max_allocated_storage  = var.db_max_allocated_storage
  db_name                   = var.db_name
  db_username               = var.db_username
  db_subnet_ids             = var.db_subnet_ids
  db_security_group_ids     = var.db_security_group_ids
  db_multi_az               = var.environment == "prod"

  oidc_provider_arn          = var.oidc_provider_arn
  oidc_issuer_url            = var.oidc_issuer_url
  service_account_namespace = var.service_account_namespace
  service_account_name      = var.service_account_name

  tags = var.tags
}
```

### `outputs.tf`

```hcl
output "bucket_name" {
  value = module.app_data.bucket_name
}

output "bucket_arn" {
  value = module.app_data.bucket_arn
}

output "replica_bucket_arn" {
  value = module.app_data.replica_bucket_arn
}

output "db_endpoint" {
  value = module.app_data.db_endpoint
}

output "db_port" {
  value = module.app_data.db_port
}

output "db_master_secret_arn" {
  description = "Secrets Manager ARN containing the RDS-managed credentials."
  value       = module.app_data.db_master_secret_arn
}

output "service_account_role_arn" {
  value = module.app_data.service_account_role_arn
}
```

## Reusable module

### `modules/app-data/versions.tf`

```hcl
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"

      configuration_aliases = [aws.replica]
    }
  }
}
```

### `modules/app-data/variables.tf`

```hcl
variable "name_prefix" {
  type = string
}

variable "environment" {
  type = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "bucket_name" {
  type = string
}

variable "enable_replication" {
  type    = bool
  default = false
}

variable "replica_bucket_name" {
  type    = string
  default = null

  validation {
    condition     = !var.enable_replication || var.replica_bucket_name != null
    error_message = "replica_bucket_name is required when replication is enabled."
  }
}

variable "db_instance_class" {
  type = string
}

variable "db_allocated_storage" {
  type    = number
  default = 20
}

variable "db_max_allocated_storage" {
  type    = number
  default = 100
}

variable "db_name" {
  type    = string
  default = "app"
}

variable "db_username" {
  type    = string
  default = "appadmin"
}

variable "db_subnet_ids" {
  type = list(string)

  validation {
    condition     = length(var.db_subnet_ids) >= 2
    error_message = "At least two subnet IDs are required."
  }
}

variable "db_security_group_ids" {
  type = list(string)
}

variable "db_multi_az" {
  type    = bool
  default = false
}

variable "oidc_provider_arn" {
  type = string
}

variable "oidc_issuer_url" {
  type = string
}

variable "service_account_namespace" {
  type = string
}

variable "service_account_name" {
  type = string
}

variable "tags" {
  type    = map(string)
  default = {}
}
```

### `modules/app-data/s3.tf`

```hcl
resource "aws_s3_bucket" "assets" {
  bucket = var.bucket_name

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-${var.environment}-assets"
  })
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = var.replica_bucket_name

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-${var.environment}-assets-replica"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

data "aws_iam_policy_document" "replication_assume_role" {
  count = var.enable_replication ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name               = "${var.name_prefix}-${var.environment}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = var.tags
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_replication ? 1 : 0

  statement {
    sid = "ReadSourceBucket"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ReadSourceVersions"

    actions = [
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "WriteReplicaVersions"

    actions = [
      "s3:ReplicateDelete",
      "s3:ReplicateObject",
      "s3:ReplicateTags"
    ]

    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name   = "${var.name_prefix}-${var.environment}-s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id       = "replicate-all"
    priority = 1
    status   = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.assets,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication
  ]
}
```

### `modules/app-data/rds.tf`

```hcl
resource "aws_db_subnet_group" "this" {
  name       = "${var.name_prefix}-${var.environment}"
  subnet_ids = var.db_subnet_ids

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-${var.environment}"
  })
}

resource "aws_db_instance" "postgres" {
  identifier = "${var.name_prefix}-${var.environment}-postgres"

  engine         = "postgres"
  engine_version = "16"

  instance_class        = var.db_instance_class
  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = var.db_name
  username = var.db_username
  port     = 5432

  # AWS generates the password and stores it encrypted in Secrets Manager.
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = var.db_security_group_ids

  multi_az            = var.db_multi_az
  publicly_accessible = false

  deletion_protection      = true
  backup_retention_period  = 7
  backup_window            = "03:00-04:00"
  maintenance_window       = "sun:04:00-sun:05:00"
  auto_minor_version_upgrade = true

  copy_tags_to_snapshot = true
  skip_final_snapshot   = false
  final_snapshot_identifier = (
    "${var.name_prefix}-${var.environment}-postgres-final"
  )

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  tags = merge(var.tags, {
    Name = "${var.name_prefix}-${var.environment}-postgres"
  })

  lifecycle {
    prevent_destroy = true
  }
}
```

### `modules/app-data/iam.tf`

```hcl
locals {
  oidc_issuer = trimsuffix(
    trimprefix(var.oidc_issuer_url, "https://"),
    "/"
  )
}

data "aws_iam_policy_document" "service_account_trust" {
  statement {
    sid     = "AllowAssumeRoleWithWebIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_issuer}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_issuer}:sub"
      values = [
        "system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"
      ]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = "${var.name_prefix}-${var.environment}-web-app"
  assume_role_policy = data.aws_iam_policy_document.service_account_trust.json

  tags = var.tags
}

data "aws_iam_policy_document" "service_account" {
  statement {
    sid = "ListAssets"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket"
    ]

    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid = "ManageAssetObjects"

    actions = [
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject"
    ]

    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid = "ReadDatabaseCredentials"

    actions = [
      "secretsmanager:DescribeSecret",
      "secretsmanager:GetSecretValue"
    ]

    resources = [
      aws_db_instance.postgres.master_user_secret[0].secret_arn
    ]
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${var.name_prefix}-${var.environment}-web-app"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account.json
}
```

### `modules/app-data/outputs.tf`

```hcl
output "bucket_name" {
  value = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "replica_bucket_arn" {
  value = try(aws_s3_bucket.replica[0].arn, null)
}

output "db_endpoint" {
  value = aws_db_instance.postgres.address
}

output "db_port" {
  value = aws_db_instance.postgres.port
}

output "db_master_secret_arn" {
  value = aws_db_instance.postgres.master_user_secret[0].secret_arn
}

output "service_account_role_arn" {
  value = aws_iam_role.service_account.arn
}
```

## Environment files

Replace the example account, OIDC, subnet, security group, and bucket values.

### `environments/dev.tfvars`

```hcl
environment = "dev"
aws_region  = "us-east-1"
name_prefix = "example-app"

bucket_name = "example-app-dev-assets-123456789012"

db_instance_class          = "db.t3.micro"
db_allocated_storage       = 20
db_max_allocated_storage   = 50
db_subnet_ids              = ["subnet-dev-private-a", "subnet-dev-private-b"]
db_security_group_ids      = ["sg-dev-database"]

oidc_provider_arn = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE"
oidc_issuer_url   = "https://oidc.eks.us-east-1.amazonaws.com/id/DEVEXAMPLE"

service_account_namespace = "app"
service_account_name      = "web-app"

tags = {
  Application = "example-app"
  Owner       = "platform"
}
```

